// Retire this folder's former worker/cache without touching application records.
(async function(){
 if(!/^https?:$/.test(location.protocol))return;
 const root=WhiteBird.root,key='WhiteBird:RetireCache:'+root.href;
 try{if(sessionStorage.getItem(key))return;}catch{}
 if(navigator.serviceWorker){
  const expected=new URL('sw.js',root).href;
  for(const registration of await navigator.serviceWorker.getRegistrations()){
   const worker=registration.active||registration.waiting||registration.installing;
   if(registration.scope===root.href&&worker&&new URL(worker.scriptURL).href===expected)await registration.unregister();
  }
 }
 if(globalThis.caches){
  for(const name of await caches.keys()){
   if(!name.startsWith('whitebird-flat-')&&!name.startsWith('shion-qr-offline-'))continue;
   const cache=await caches.open(name);
   for(const request of await cache.keys())if(new URL('./',request.url).href===root.href)await cache.delete(request);
   if(!(await cache.keys()).length)await caches.delete(name);
  }
 }
 try{sessionStorage.setItem(key,'1');}catch{}
})().catch(()=>{});
